export const fmt = (s: string, vars: Record<string, string | number>) => s.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? ""));

export const WHATSAPP = "5565984046666";
export const waLink = (text: string, number = WHATSAPP) => `https://wa.me/${number}?text=${encodeURIComponent(text)}`;

export function rememberLang(lang: Lang) {
  try { document.cookie = `lang=${lang}; path=/; max-age=31536000; samesite=lax`; } catch { /* ignore */ }
  try { localStorage.setItem("lang", lang); } catch { /* ignore */ }
}

