/** "YYYY-MM-DDTHH:mm" → "23/11/2026 às 10:00" (EN "11/23/2026 at 10:00"). */
export function waWhen(v: string | undefined, lang: Lang) {
  if (!v) return "";
  const [date = "", time = ""] = v.split("T");
  const [y, m, d] = date.split("-");
  if (!y || !m || !d) return "";
  return `${lang === "en" ? `${m}/${d}/${y}` : `${d}/${m}/${y}`} ${convText[lang].wa.at} ${time.slice(0, 5) || "10:00"}`;
}
const waUsd = (n: number, lang: Lang) => `US$ ${new Intl.NumberFormat(lang === "en" ? "en-US" : lang === "es" ? "es-ES" : "pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n)}`;
/** Customer-voiced WhatsApp pre-fill per page type; falls back to the generic text when context is missing. */
export function waMessage(lang: Lang, ctx: { kind: "general" } | { kind: "car"; car: string; city: string; pickup?: string | undefined; ret?: string | undefined } | { kind: "results"; city: string; pickup?: string | undefined; ret?: string | undefined } | { kind: "checkout"; car: string; city: string; pickup: string; ret: string; total?: number | null | undefined; step: number }) {
  const w = convText[lang].wa;
  if (ctx.kind === "car") { const from = waWhen(ctx.pickup, lang), to = waWhen(ctx.ret, lang); return from && to ? fmt(w.carDates, { car: ctx.car, city: ctx.city, from, to }) : fmt(w.car, { car: ctx.car, city: ctx.city }); }
  if (ctx.kind === "results") { const from = waWhen(ctx.pickup, lang), to = waWhen(ctx.ret, lang); return from && to ? fmt(w.resultsDates, { city: ctx.city, from, to }) : fmt(w.results, { city: ctx.city }); }
  if (ctx.kind === "checkout") {
    const strip = (s: string) => s.replace(` ${w.at} `, " ");
    return fmt(w.checkout, { car: ctx.car, city: ctx.city, from: strip(waWhen(ctx.pickup, lang)), to: strip(waWhen(ctx.ret, lang)), total: ctx.total != null ? fmt(w.total, { amt: waUsd(ctx.total, lang) }) : "", step: w.steps[Math.max(0, Math.min(3, ctx.step))] ?? w.steps[0] });
  }
  return w.general;
}

/** Short substitute offer (WhatsApp). difference = new total − original total. */
export function substituteWaText(lang: Lang, o: { name: string; orig: string; sub: string; newTotal: number; difference: number; link: string; balanceOnly?: boolean }) {
  const u = (n: number) => `$${n.toFixed(2)}`;
  const T = {
    en: { hi: "Hi {name}! Your Onic Car Rentals rental is approved, but the {orig} isn't available for your dates. We're offering the {sub}. New total {total}.", extra: "Difference to pay: {amt}.", refund: "Refund to you: {amt}.", lower: "Refund to you: {amt}.", none: "No price difference.", go: "Accept or decline here: {link}" },
    pt: { hi: "Olá {name}! Sua locação na Onic Car Rentals foi aprovada, mas o {orig} não está disponível nas suas datas. Oferecemos o {sub}. Novo total {total}.", extra: "Diferença a pagar: {amt}.", refund: "Reembolso para você: {amt}.", lower: "Reembolso para você: {amt}.", none: "Sem diferença de preço.", go: "Aceite ou recuse aqui: {link}" },
    es: { hi: "¡Hola {name}! Tu alquiler en Onic Car Rentals fue aprobado, pero el {orig} no está disponible en tus fechas. Te ofrecemos el {sub}. Nuevo total {total}.", extra: "Diferencia a pagar: {amt}.", refund: "Reembolso para ti: {amt}.", lower: "Reembolso para ti: {amt}.", none: "Sin diferencia de precio.", go: "Acepta o rechaza aquí: {link}" },
  }[lang];
  const diff = o.difference > 0 ? fmt(T.extra, { amt: u(o.difference) }) : o.difference < 0 ? fmt(o.balanceOnly ? T.lower : T.refund, { amt: u(-o.difference) }) : T.none;
  return [fmt(T.hi, { name: o.name, orig: o.orig, sub: o.sub, total: u(o.newTotal) }), diff, fmt(T.go, { link: o.link })].join(" ");
}

/** Old owner templates never reintroduce a rental payment hold or a pay-later request. Safe custom templates stay intact. */
export function currentPaymentMessage(lang: Lang, kind: "approved" | "confirmed" | "declined" | "expired", saved: string) {
  const stale = /card hold|remaining balance|payment deadline|bloqueio|saldo restante|pague o restante|prazo de pagamento|retención|saldo pendiente|fecha límite de pago|\[balance\]|\[deadline\]/i.test(saved);
  if (saved.trim() && !stale) return saved;
  return kind === "approved" || kind === "confirmed" ? t(lang).booking.approvedNoteFull : t(lang).booking.refundedNote;
}

